+export type ParsedStatus = {
+	branch: string | null;
+	hasUpstream: boolean;
+	ahead: number;
+	behind: number;
+	staged: ParsedStatusEntry[];
+	unstaged: ParsedStatusEntry[];
+	untracked: string[];
+};
