+	const empty: SourceControlState = {
+		environmentId,
+		root: null,
+		branch: null,
+		hasUpstream: false,
+		ahead: 0,
+		behind: 0,
+		staged: [],
+		unstaged: [],
+		untracked: [],
+		commits: [],
+	};
