+		status.untracked.map(async (path, index): Promise<SourceControlFile> => {
+			const text =
+				options.readUntracked && index < UNTRACKED_COUNT_LIMIT
+					? await options.readUntracked(path).catch(() => null)
+					: null;
+			return {
+				path,
+				status: "?",
