+		environmentId,
+		root,
+		branch: status.branch,
+		hasUpstream: status.hasUpstream,
+		ahead: status.ahead,
+		behind: status.behind,
+		staged: withCounts(status.staged, stagedCounts),
+		unstaged: withCounts(status.unstaged, unstagedCounts),
