+export type CommitDetails = {
+	environmentId: string;
+	sha: string;
+	files: CommitFile[];
+};
+
+// Git's empty tree: what a root commit is compared against.
+const EMPTY_TREE = "4b825dc642cb6eb9a060e54bf8d69288fbee4904";
