+	const [nameStatus, numstat] = await Promise.all([
+		git(["diff", "--name-status", "-z", "-M", base, sha]),
+		git(["diff", "--numstat", "-z", "-M", base, sha]).then(
+			parseNumstat,
+			() => new Map(),
+		),
+	]);
