+		environmentId,
+		sha,
+		files: parseNameStatus(nameStatus).map((file) => ({
+			...file,
+			additions: numstat.get(file.path)?.additions ?? null,
+			deletions: numstat.get(file.path)?.deletions ?? null,
+		})),
