+function showBlob(
+	git: GitRunner,
+	rev: string,
+	path: string,
+): Promise<string | undefined> {
+	return git(["show", `${rev}:${path}`]).catch((error: unknown) => {
+		if (MISSING_OBJECT.test(String(error))) return undefined;
+		throw error;
+	});
