+/** Mode and object of a path in a tree (`rev`) or, for `null`, the index. */
+async function treeEntry(
+	git: GitRunner,
+	rev: string | null,
+	path: string,
+): Promise<TreeEntry | undefined> {
+	const output = await git(
+		rev === null
