+/** One side of a diff: a submodule renders as its commit, anything else as the blob. */
+async function sideContents(
+	git: GitRunner,
+	rev: string,
+	path: string,
+	entry: TreeEntry | undefined,
+): Promise<string | undefined> {
+	return entry?.mode === GITLINK
